"""The join of two sheaf-equivalence classes is generated by composition alone.

Setting: towers of sets (presheaves on the chain 0 < 1 < ... < N) and the ideal topologies J_A, J_B
of two sets A, B of points (D_A = arrows n -> m with a point of A in [n, m]).  A sieve on m is an
initial segment {n < t}.  For topologies J, J' with closure operators j, j' on sieves, a map f lies in
U_k iff for every y the sieve {b : y.b in im f} and for every pair f(x) = f(x') the sieve
{b : x.b = x'.b} are k-reachable, i.e. contain the identity after applying (j j')^k.
Checked here on random towers and random maps f:
  * U_k computed by closures agrees with "locally bijective along (D_A D_B)^k";
  * every f in U_k factors as 2k surjections (quotients by ker f meets the j'-closure of the
    diagonal, alternately for J' and J) followed by 2k injections (alternating closures of im f),
    each factor lying in W_{J'} or W_J as claimed, and the composite is f;
  * so W_J v W_J' = U = union of the U_k, the closure of W_J u W_J' under composition.
"""
import random, itertools as it, sys

def amax(A, m):
    pts = [a for a in A if a <= m]
    return max(pts) if pts else None

def covering(A, m, t):          # sieve {n < t} on m is J_A-covering
    a = amax(A, m)
    return a is None or t > a

def j(A, m, t):                 # closure of the sieve {n < t} on m: {n : pullback covering}
    s = 0
    for n in range(m + 1):
        if covering(A, n, min(t, n + 1)): s = n + 1
        else: break
    return s

def reach(A, B, m, t, k):       # id_m in (j_A j_B)^k ({n<t}) ?
    for _ in range(k): t = j(A, m, j(B, m, t))
    return t == m + 1

# towers: X = (sets X[c], maps res[c]: X[c] -> X[c-1]) ; map f = (f[c]) ; elements are ints
def rand_tower_map(N, rng):
    Y = [list(range(rng.randrange(1, 4))) for c in range(N + 1)]
    Yres = [None] + [[rng.randrange(len(Y[c - 1])) for _ in Y[c]] for c in range(1, N + 1)]
    X, f, Xres = [], [], [None]
    for c in range(N + 1):
        fib = [[] for _ in Y[c]]; els = []
        for y in range(len(Y[c])):
            for _ in range(rng.randrange(0, 3)): fib[y].append(len(els)); els.append(y)
        X.append(list(range(len(els)))); f.append(els)
        if c > 0:
            r = []
            for x in X[c]:
                y0 = Yres[c][els[x]]; cand = [x0 for x0 in X[c - 1] if f[c - 1][x0] == y0]
                if not cand: return None
                r.append(rng.choice(cand))
            Xres.append(r)
    return (X, Xres), (Y, Yres), f

def restrict(T, c, x, n):       # restrict x in T(c) to level n <= c
    S, res = T
    for d in range(c, n, -1): x = res[d][x]
    return x

def im_sieve(T, Tr, f, c, y):   # threshold t with {n < t} = {n : y|_n in im f_n}
    t = 0
    for n in range(c + 1):
        if restrict(Tr, c, y, n) in f[n]: t = n + 1
        else: break
    return t

def eq_sieve(T, c, x, xp):
    t = 0
    for n in range(c + 1):
        if restrict(T, c, x, n) == restrict(T, c, xp, n): t = n + 1
        else: break
    return t

def in_Uk(A, B, Xt, Yt, f, k):
    N = len(Xt[0]) - 1
    for c in range(N + 1):
        for y in range(len(Yt[0][c])):
            if not reach(A, B, c, im_sieve(Xt, Yt, f, c, y), k): return False
        for x in Xt[0][c]:
            for xp in Xt[0][c]:
                if f[c][x] == f[c][xp] and not reach(A, B, c, eq_sieve(Xt, c, x, xp), k): return False
    return True

def ideal_power(A, B, c, k):    # {n : (n -> c) in (D_A D_B)^k}, chains n <= b_1 <= a_1 <= ... <= a_k <= c
    ok = set()
    for n in range(c + 1):
        pos = n; good = True
        for _ in range(k):
            bs = [b for b in B if pos <= b <= c]
            if not bs: good = False; break
            pos = min(bs)
            as_ = [a for a in A if pos <= a <= c]
            if not as_: good = False; break
            pos = min(as_)
        if good: ok.add(n)
    return ok

def in_Uk_ideal(A, B, Xt, Yt, f, k):   # locally bijective along (D_A D_B)^k
    N = len(Xt[0]) - 1
    for c in range(N + 1):
        P = ideal_power(A, B, c, k)
        for y in range(len(Yt[0][c])):
            if any(restrict(Yt, c, y, n) not in f[n] for n in P): return False
        for x in Xt[0][c]:
            for xp in Xt[0][c]:
                if f[c][x] == f[c][xp] and any(restrict(Xt, c, x, n) != restrict(Xt, c, xp, n) for n in P): return False
    return True

def in_W(A, Xt, Yt, f):         # locally bijective along D_A
    N = len(Xt[0]) - 1
    for c in range(N + 1):
        a = amax(A, c)
        if a is None: continue
        for y in range(len(Yt[0][c])):
            if restrict(Yt, c, y, a) not in f[a]: return False
        for x in Xt[0][c]:
            for xp in Xt[0][c]:
                if f[c][x] == f[c][xp] and restrict(Xt, c, x, a) != restrict(Xt, c, xp, a): return False
    return True

def quotient(Xt, f, A):         # X / (ker f  meets  j_A-closure of the diagonal)
    N = len(Xt[0]) - 1; cls, q = [], []
    for c in range(N + 1):
        rep = {}; qc = []
        for x in Xt[0][c]:
            found = None
            for xp in rep:
                if f[c][x] == f[c][xp] and covering(A, c, eq_sieve(Xt, c, x, xp)): found = rep[xp]; break
            if found is None: found = 0 if not rep else max(rep.values()) + 1
            rep[x] = found; qc.append(found)
        q.append(qc); cls.append(sorted(set(qc)))
    res = [None] + [[q[c - 1][Xt[1][c][next(x for x in Xt[0][c] if q[c][x] == k)]] for k in cls[c]] for c in range(1, N + 1)]
    fq = [[f[c][next(x for x in Xt[0][c] if q[c][x] == k)] for k in cls[c]] for c in range(N + 1)]
    return (cls, res), q, fq

def closure_sub(Yt, sub, A):    # j_A-closure of a subpresheaf (list of sets of elements) of Y
    N = len(Yt[0]) - 1; out = []
    for c in range(N + 1):
        keep = set()
        for y in Yt[0][c]:
            t = 0
            for n in range(c + 1):
                if restrict(Yt, c, y, n) in sub[n]: t = n + 1
                else: break
            if covering(A, c, t): keep.add(y)
        out.append(keep)
    return out

def subtower(Yt, sub):          # the subpresheaf as a tower with inclusion map
    N = len(Yt[0]) - 1; els = [sorted(sub[c]) for c in range(N + 1)]
    res = [None] + [[els[c - 1].index(Yt[1][c][y]) for y in els[c]] for c in range(1, N + 1)]
    return (list(list(range(len(e))) for e in els), res), els

def check(A, B, Xt, Yt, f, k):
    N = len(Xt[0]) - 1
    # epi part: 2k quotients, alternately along B (first) and A
    cur, curf, steps = Xt, f, []
    for i in range(2 * k):
        F = B if i % 2 == 0 else A
        Q, q, fq = quotient(cur, curf, F)
        assert in_W(F, cur, Q, q), "quotient step not in W"
        cur, curf = Q, fq; steps.append(F)
    # now cur -> im f must be injective (bijective onto image)
    for c in range(N + 1): assert len(set(curf[c])) == len(curf[c]), "epi part did not reach im f"
    # mono part: 2k closures of im f, alternately along B (first) and A
    sub = [set(f[c]) for c in range(N + 1)]
    for i in range(2 * k):
        F = B if i % 2 == 0 else A
        sub2 = closure_sub(Yt, sub, F)
        S1, e1 = subtower(Yt, sub); S2, e2 = subtower(Yt, sub2)
        inc = [[e2[c].index(e) for e in e1[c]] for c in range(N + 1)]
        assert in_W(F, S1, S2, inc), "closure step not in W"
        sub = sub2
    assert all(sub[c] == set(Yt[0][c]) for c in range(N + 1)), "mono part did not reach Y"

def main():
    rng = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 3)
    tested = inU = 0; maxk = 0; N = 7
    for trial in range(1500):
        A = frozenset(c for c in range(N + 1) if rng.random() < 0.4)
        B = frozenset(c for c in range(N + 1) if rng.random() < 0.4)
        t = None
        while t is None: t = rand_tower_map(N, rng)
        Xt, Yt, f = t; tested += 1
        for k in range(0, 2 * N + 2):
            assert in_Uk(A, B, Xt, Yt, f, k) == in_Uk_ideal(A, B, Xt, Yt, f, k), "closure and ideal formulations differ"
            if in_Uk(A, B, Xt, Yt, f, k):
                inU += 1; maxk = max(maxk, k)
                # agreement with the ideal formulation: locally bijective along (D_A D_B)^k
                check(A, B, Xt, Yt, f, k)
                break
    print(f"random towers on [0,{N}]: {tested} maps tested, {inU} lie in some U_k (max k = {maxk});")
    print("  every one factored as 2k quotients and 2k closures in W_{J_B} u W_{J_A}, composite = f: OK")

if __name__ == "__main__":
    main()
